.wpe-ess-logo { flex: none; white-space: nowrap; }
.wpe-ess-news > .wp-block-group { flex: 1 1 420px; }
.wpe-newsletter input[type=email] { background: transparent !important; border: 0 !important; box-shadow: none !important; padding: 8px 0 !important; height: auto; }
.wpe-ess-foot__list { padding-left: 0 !important; }
.wpe-newsletter .wpe-contact-form__hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
.wpe-newsletter { align-items: center; }
.wpe-ess-logo { gap: 14px; }

/* Responsive grids: 3/4 columns on desktop, 2 on tablet, 1 on phones. */
@media (max-width: 1024px) {
	.wpe-ess-grid.is-layout-grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
	.wpe-ess-feature__cols { flex-wrap: wrap !important; }
	.wpe-ess-feature__cols > .wp-block-column { flex-basis: 100% !important; }
}
@media (max-width: 640px) {
	.wpe-ess-grid.is-layout-grid { grid-template-columns: minmax(0, 1fr) !important; }
	.wpe-ess-logo__text { display: none; }
	.wpe-ess-actions .wp-block-buttons { display: none; }
	.wpe-ess-hero__stats { gap: 16px 40px; }
	.wpe-ess-hero__stats b { font-size: 26px; }
	.wpe-ess-band, .wpe-ess-news { flex-direction: column; align-items: flex-start !important; }
	.wpe-newsletter { width: 100%; box-sizing: border-box; }
	.wpe-ess-foot__legal { flex-wrap: wrap; gap: 12px; }
}
.wpe-ess-pill a, .wpe-ess-pill b { white-space: nowrap; }
.wpe-ess-pill a { white-space: normal; }
.wpe-ess-card__price code, .wpe-ess-card__meta code { border: 0 !important; }
@media (max-width: 640px) { .wpe-ess-news > .wp-block-group, .wpe-ess-band > .wp-block-group { flex-basis: auto !important; } }

/* Contact, quote and service pages. */
.wpe-ess-contact-cols { gap: 32px; align-items: flex-start !important; }
.wpe-ess-side { background: var(--wp--preset--color--surface, #fff); border: 1px solid var(--wp--preset--color--border, #e3e8f2); border-radius: 16px; padding: 28px; display: flex; flex-direction: column; gap: 14px; }
.wpe-ess-side__title { font-weight: 700; font-size: 18px; margin: 0; }
.wpe-ess-side__muted, .wpe-ess-mini { color: var(--wp--preset--color--text-muted, #5b6478); font-size: 14px; margin: 0; }
.wpe-ess-side__row { display: flex; gap: 12px; align-items: flex-start; padding: 12px 0; border-top: 1px solid var(--wp--preset--color--border, #e3e8f2); }
.wpe-ess-card--ink { background: var(--wp--preset--color--text, #0e1630) !important; color: #fff; }
