.wpe-ess-card--soft { background: var(--wp--preset--color--primary-soft, #fdf1e6) !important; }
.wpe-ess-card--alt { background: var(--wp--preset--color--surface-alt, #f3f6fc) !important; }
.wpe-ess-mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }
.wpe-ess-trust { display: flex; flex-wrap: wrap; gap: 12px 32px; color: var(--wp--preset--color--text-muted, #5b6478); font-size: 14px; }
.wpe-ess-form__title { font-size: 22px; font-weight: 700; margin: 0 0 8px; }
.wpe-ess-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px; }
.wpe-ess-crumb--light, .wpe-ess-crumb--light a { color: rgba(255,255,255,.8); }
