.wpe-ess-num { display: inline-grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: var(--wp--preset--color--primary-soft, #fdf1e6); color: var(--wp--preset--color--primary, #ec7d1a); font-weight: 700; }

/* WPForms in theme colours. */
/* Footer newsletter: one white pill with the email field and a navy Subscribe button (Figma 240:215). */
.wpe-ess-news .wpforms-container { margin: 0 !important; flex: 0 1 440px; }
.wpe-ess-news .wpforms-form { display: flex; align-items: center; gap: 8px; background: #fff; border: 1px solid rgba(11,26,61,.12); border-radius: 999px; padding: 6px 6px 6px 20px; }
.wpe-ess-news .wpforms-form > p, .wpe-ess-news .wpforms-form br, .wpe-ess-news .wpforms-field-container > p { display: none; }
.wpe-ess-news .wpforms-field-container { flex: 1; min-width: 0; }
.wpe-ess-news .wpforms-field { padding: 0 !important; margin: 0 !important; }
