.wpe-ess-news .wpforms-field input:not([type=checkbox]):not([type=radio]) { width: 100%; max-width: none !important; height: 40px; padding: 0 !important; border: 0 !important; background: transparent !important; color: #0B1A3D; box-shadow: none !important; }
.wpe-ess-news .wpforms-field input:focus { outline: none; }
.wpe-ess-news .wpforms-form:focus-within { box-shadow: 0 0 0 3px rgba(11,26,61,.25); }
.wpe-ess-news .wpforms-field input::placeholder { color: #5B6680; }
.wpe-ess-news .wpforms-submit-container { margin: 0 !important; padding: 0 !important; }
.wpe-ess-news .wpforms-container button[type=submit] { height: 40px; padding: 0 20px !important; background: #0B1A3D !important; color: #fff !important; font-size: 14px; }
