.wpe-ess-news .wpforms-confirmation-container-full { margin: 0; border-radius: 16px; }
@media (max-width: 640px) { .wpe-ess-news .wpforms-container { flex-basis: 100%; } }
@media (max-width: 1024px) { .wpe-ess-contact-cols { flex-wrap: wrap !important; } .wpe-ess-contact-cols > .wp-block-column { flex-basis: 100% !important; } }
.wpe-ess-side__row a { overflow-wrap: normal; word-break: normal; white-space: nowrap; }
.wpe-ess-side__row > :last-child { text-align: right; }
ul.wpe-ess-facts { list-style: none; padding: 0; margin: 8px 0 0; max-width: 560px; }
.wpe-ess-facts li { display: flex; flex-direction: column; gap: 4px; padding-left: 14px; border-left: 2px solid var(--wp--preset--color--primary, #ec7d1a); }
.wpe-ess-facts span { font-size: 13px; color: rgba(255,255,255,.7); }
.wpe-ess-facts b { font-size: 18px; color: #fff; }

/* Contact — proof, recent work, testimonial, team and map. */
.wpe-ess-proof { background: var(--wp--preset--color--surface-alt, #f3f6fc); border-radius: 16px; padding: 20px 24px; }
.wpe-ess-proof__n { font-size: 26px; font-weight: 800; color: var(--wp--preset--color--secondary, #1f48a6); margin: 0; }
.wpe-ess-clients { display: flex; flex-wrap: wrap; gap: 12px 40px; align-items: center; justify-content: flex-start; margin-top: 28px; color: var(--wp--preset--color--text-muted, #5b6478); font-size: 14px; }
.wpe-ess-clients b { font-size: 18px; letter-spacing: -.01em; }
.wpe-ess-clients span { flex-basis: 100%; }
.wpe-ess-work { padding: 0 !important; overflow: hidden; }
.wpe-ess-work figure { margin: 0; }
.wpe-ess-work img { display: block; width: 100%; object-fit: cover; object-position: top; }
.wpe-ess-work__body { padding: 20px 24px 24px; }
.wpe-ess-work__result { color: var(--wp--preset--color--success, #16a34a); font-size: 14px; font-weight: 600; margin: 8px 0 0; }
.wpe-ess-quote { gap: 24px !important; padding: 32px 40px !important; margin-top: 24px; }
.wpe-ess-quote__avatar { flex: none; margin: 0; }
.wpe-ess-quote__avatar img { width: 72px; height: 72px; border-radius: 50%; object-fit: cover; }
.wpe-ess-quote__text { font-size: 18px; color: #fff; margin: 0 0 8px; }
.wpe-ess-quote__by { font-size: 13px; color: rgba(255, 255, 255, .7); margin: 0; }
.wpe-ess-team__img { margin: 0 0 10px; }
.wpe-ess-team__img img { border-radius: 14px; width: 100%; object-fit: cover; }
.wpe-ess-team p { margin: 0; }
.wpe-ess-map { position: relative; border-radius: 20px; overflow: hidden; border: 1px solid var(--wp--preset--color--border, #e3e8f2); min-height: 420px; }
.wpe-ess-map iframe { display: block; width: 100%; height: 420px; border: 0; }
.wpe-ess-map__card { position: absolute; left: 20px; bottom: 20px; background: #fff; border-radius: 14px; padding: 14px 18px; display: grid; gap: 4px; font-size: 14px; box-shadow: 0 10px 30px rgba(0, 0, 0, .12); color: #0e1630; }
.wpe-ess-map__card span { color: #5b6478; font-size: 13px; }
.wpe-ess-map__card a { color: var(--wp--preset--color--secondary, #1f48a6); font-weight: 600; }
@media (max-width: 781px) { .wpe-ess-quote { flex-direction: column; align-items: flex-start !important; } .wpe-ess-clients { justify-content: flex-start; } }
.wpe-ess-quote__avatar { width: 72px !important; } .wpe-ess-quote > .wp-block-group { flex: 1; }
@media (max-width: 640px) {
	.wpe-ess-grid.is-layout-grid:has(> .wpe-ess-proof), .wpe-ess-grid.is-layout-grid:has(> .wpe-ess-team), .wpe-ess-grid.is-layout-grid:has(> .wpe-ess-mini) { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 12px !important; }
	.wpe-ess-proof { padding: 14px 16px; }
	.wpe-ess-proof__n { font-size: 20px; }
	.wpe-ess-team__img img { aspect-ratio: 1 / 1; }
	.wpe-ess-mini { padding: 14px !important; }
	.wpe-ess-side__row { flex-direction: column; gap: 2px; }
	.wpe-ess-side__row > :last-child { text-align: left; }
	.wpe-ess-map, .wpe-ess-map iframe { min-height: 320px; height: 320px; }
}
.wpe-ess-release__title small { font-size: 14px; font-weight: 400; color: var(--wp--preset--color--text-muted, #5b6478); margin-left: 8px; }
.wpe-ess-release { list-style: none; padding: 0; margin: 12px 0 0; display: grid; gap: 10px; }
.wpe-ess-tag { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 999px; margin-right: 8px; background: #e8eefb; color: var(--wp--preset--color--secondary, #1f48a6); }
.wpe-ess-tag--fixed { background: var(--wp--preset--color--primary-soft, #fdf1e6); color: #9a4b0a; }
.wpe-ess-vote { font-size: 13px; color: var(--wp--preset--color--secondary, #1f48a6); margin: 6px 0 0; }

/* Phone/tablet header: menu button left, logo next to it, actions right (the menu no longer stretches). */
@media (max-width: 1024px) {
	.wpe-ess-header .wpe-header__inner > .wp-block-navigation { flex: 0 0 auto; }
	.wpe-ess-header .wpe-header__inner > .wpe-ess-logo { margin-inline-end: auto; }
}

/* ── Kit bridge: the .ess-* rules above style WPEssential kit elements exactly like the core blocks they replace. */
.wpe-heading[class*="ess-"] .wpe-heading__title,.wpe-heading[class*="has-"] .wpe-heading__title{font:inherit;color:inherit;letter-spacing:inherit;line-height:inherit;text-transform:inherit;text-align:inherit;margin:0}
.wpe-text[class*="ess-"] .wpe-text__body>*,.wpe-text[class*="is-style-"] .wpe-text__body>*{margin:0}
.wpe-text .wpe-text__body>*+*{margin-top:.6em}
.wpe-container.wpe-buttons>.wpe-container__inner{gap:12px}
.wpe-cols>.wpe-container__inner{display:flex;gap:var(--wp--style--block-gap,2rem)}
.wpe-col{flex:1 1 0;min-width:0}
.wpe-col--w34{flex:0 0 calc(34% - 1rem)}.wpe-col--w38{flex:0 0 calc(38% - 1rem)}.wpe-col--w40{flex:0 0 calc(40% - 1rem)}.wpe-col--w42{flex:0 0 calc(42% - 1rem)}.wpe-col--w44{flex:0 0 calc(44% - 1rem)}.wpe-col--w48{flex:0 0 calc(48% - 1rem)}.wpe-col--w50{flex:0 0 calc(50% - 1rem)}.wpe-col--w52{flex:0 0 calc(52% - 1rem)}.wpe-col--w56{flex:0 0 calc(56% - 1rem)}.wpe-col--w58{flex:0 0 calc(58% - 1rem)}.wpe-col--w62{flex:0 0 calc(62% - 1rem)}.wpe-col--w66{flex:0 0 calc(66% - 1rem)}
@media (max-width:781px){.wpe-cols:not(.wpe-cols--keep)>.wpe-container__inner{flex-wrap:wrap}.wpe-cols:not(.wpe-cols--keep) .wpe-col{flex:1 1 100%}}
.wpe-container.is-grid.wpe-grid-min-11rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(11rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-12rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(12rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-13rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(13rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-14rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(14rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-16rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(16rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-17rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(17rem,100%),1fr))}.wpe-container.is-grid.wpe-grid-min-18rem>.wpe-container__inner{grid-template-columns:repeat(auto-fit,minmax(min(18rem,100%),1fr))}

/* Kit header bridge: menu/search/sign-in from wpessential kit elements. */
.wpe-ess-header .wpe-container__inner > :not(.wpe-container) { flex: none; }
.wpe-ess-header .wpe-header__inner { flex: 1 1 auto; width: 100%; }
.wpe-ess-header .wpe-header__inner > .wpe-container__inner { align-items: center; }
.wpe-ess-header .wpe-menu__items { flex-wrap: nowrap; justify-content: center; gap: 4px; }
.wpe-ess-header .wpe-container__inner > .wpe-menu { flex: 1 1 auto; }
.wpe-ess-header .wpe-menu__desktop { display: flex; justify-content: center; gap: 4px; margin: 0; padding: 0; list-style: none; background: none; }
.wpe-ess-header .wpe-menu__desktop a { display: block; padding: 8px 14px; border-radius: 999px; font-size: 15px; color: var(--wp--preset--color--text); text-decoration: none; }
